import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest case and base premiums ---
  it.todo("empty item list → premium 5 G (only the processing fee)");
  it.todo("a plain sword → base premium 100 G + 10 G first insurance + 5 G fee = 115 G");
  it.todo("a plain amulet → base premium 60 G + 6 G first insurance + 5 G fee = 71 G");
  it.todo("a plain staff → base premium 80 G + 8 G first insurance + 5 G fee = 93 G");
  it.todo("a plain potion → base premium 40 G + 4 G first insurance + 5 G fee = 49 G");
  it.todo("a single rune → base premium 25 G + 2.5 G first insurance + 5 G fee = 33 G (rounded up)");
  it.todo("a single moonstone → base premium 25 G + 2.5 G first insurance + 5 G fee = 33 G (rounded up)");

  // --- Components: block of 3 alike ---
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // --- Premium modifiers in isolation ---
  it.todo("cursed sword adds a 50 % risk surcharge on its own base premium (+50 G)");
  it.todo("sword with enchantment 5 adds a 30 % high-enchantment surcharge (+30 G)");
  it.todo("sword with enchantment 4 gets no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 gets both surcharges (+50 G and +30 G)");
  it.todo("customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
  it.todo("customer with 1 year with MHPCO receives no loyalty discount");
  it.todo("a first insurance carries a 10 % initial assessment surcharge");
  it.todo("the second quote in a scenario receives a 15 % follow-up contract discount");
  it.todo("a 5 G processing fee is added to every premium");

  // --- Modifier scope on multi-item policies ---
  it.todo("cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G → 210 G before further modifiers and fee");
  it.todo("item-specific modifiers apply per item; policy-wide modifiers apply to the policy base premium; the fee is added last");

  // --- Rounding in MHPCO's favour ---
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");

  // --- Integration examples ---
  it.todo("newcomer with a cursed sword (0 years, no previous contract) → premium 165 G");
  it.todo("long-standing customer's second contract, cursed sword enchantment 7 → premium 160 G");

  // --- Claim: standard reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");

  // --- Claim: special clauses ---
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)");

  // --- Claim: rounding ---
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");

  // --- Claim: insurance sum and cap ---
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G (block discount affects the premium only)");
  it.todo("sword insured (cap 2000 G), two successive claims of 1500 G each → first payout 1400 G, remaining cap 600 G");
  it.todo("second of two successive 1500 G claims → payout 600 G, remaining cap 0 G (desired 1400 G reduced to remaining cap)");

  // --- Multiple items of the same type ---
  it.todo("a policy covers two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("two sword damage entries on a two-sword policy → each treated as a separate damage with its own deductible");
  it.todo("more damage entries of a type than the policy covers → the whole claim is rejected");

  // --- Edge cases / errors ---
  it.todo("quote with an unknown item type (e.g. broomstick) → error");
  it.todo("claim referencing an item not part of the policy (amulet damaged when only a sword insured) → error");
  it.todo("claim referencing a damage entry with an unknown item type → error");
  it.todo("claim containing a damage entry with amount -200 → error");

  // --- CLI contract ---
  it.todo("CLI reads a scenario from stdin and writes {results: [...]} to stdout in step order");
  it.todo("CLI writes premium for quote steps and payout + remainingCap for claim steps");
  it.todo("CLI exits with a non-zero status code and writes an error to stderr for an unknown item type, writing no results to stdout");
  it.todo("CLI exits with a non-zero status code and writes an error to stderr for an invalid claim");
});

