const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const ALIKE_ITEMS_PER_BLOCK = 3;
const BLOCK_BASE_PREMIUM = 60;

const basePremiumForAlikeItems = (type: string, count: number): number =>
  count === ALIKE_ITEMS_PER_BLOCK
    ? BLOCK_BASE_PREMIUM
    : count * BASE_PREMIUMS[type];

const countByType = (items: Item[]): Map<string, number> =>
  items.reduce(
    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
    new Map<string, number>(),
  );

const policyBasePremium = (items: Item[]): number =>
  [...countByType(items)].reduce(
    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
    0,
  );

const quotePremium = (items: Item[]): number => {
  const policyBase = policyBasePremium(items);
  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
  return Math.ceil(policyBase + firstInsuranceSurcharge + PROCESSING_FEE);
};

const runStep = (step: Step): StepResult => ({
  premium: quotePremium((step as QuoteStep).items),
});

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

