const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

const insuranceSum = (items: Item[]): number =>
  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);

const payoutCap = (items: Item[]): number =>
  insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;

const damagePayout = (damage: Damage): number =>
  damage.amount - DEDUCTIBLE_PER_DAMAGE;

const claimResult = (step: ClaimStep, policyItems: Item[]): ClaimResult => {
  const payout = step.incident.damages.reduce(
    (total, damage) => total + damagePayout(damage),
    0,
  );
  return { payout, remainingCap: payoutCap(policyItems) - payout };
};

const runStep = (
  step: Step,
  contract: Contract,
  steps: Step[],
): StepResult => {
  if (step.op === "claim") {
    return claimResult(step, (steps[step.policy] as QuoteStep).items);
  }
  return { premium: quotePremium(step.items, contract) };
};

/** The contract ordinal of a step: how many quotes precede it. */
const contractOrdinalOf = (steps: Step[], index: number): number =>
  steps.slice(0, index).filter((step) => step.op === "quote").length;

export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
  results: steps.map((step, index) =>
    runStep(step, { customer, ordinal: contractOrdinalOf(steps, index) }, steps),
  ),
});

