import { describe, it, expect } from "vitest";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const CLI = fileURLToPath(new URL("./cli.ts", import.meta.url));

interface CliRun {
  status: number;
  stdout: string;
  stderr: string;
}

/** Runs the claim-office CLI with the given stdin, capturing its output. */
const runCli = (stdin: string): CliRun => {
  const { status, stdout, stderr } = spawnSync("npx", ["tsx", CLI], {
    input: stdin,
    encoding: "utf8",
  });
  return { status: status ?? 1, stdout, stderr };
};

describe("claim-office CLI", () => {
  it("reads a scenario from stdin and writes {results: [...]} to stdout in step order", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 5 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
          ],
        },
        {
          op: "claim",
          policy: 0,
          incident: {
            cause: "fire",
            damages: [{ itemType: "amulet", amount: 200 }],
          },
        },
      ],
    };

    const { status, stdout } = runCli(JSON.stringify(scenario));

    // quote: 60 base − 12 loyalty (5 years) + 6 first insurance + 5 fee = 59
    // claim: 200 − 100 deductible = 100; insurance sum 600 → cap 1200 → 1100 left
    expect(status).toBe(0);
    expect(JSON.parse(stdout)).toEqual({
      results: [{ premium: 59 }, { payout: 100, remainingCap: 1100 }],
    });
  }, 30000);

  it.todo("writes premium for quote steps and payout + remainingCap for claim steps");
  it.todo("exits with a non-zero status code and writes an error to stderr for an unknown item type, writing no results to stdout");
  it.todo("exits with a non-zero status code and writes an error to stderr for an invalid claim");
});

